import { injectedAgentNativeConfig } from "./app-config.js";
import { clientBuildId } from "./build-compatibility.js";
function readPackageVersions(value) {
    if (!value || typeof value !== "object") {
        return {};
    }
    return Object.fromEntries(Object.entries(value)
        .filter(([name, version]) => name.startsWith("@agent-native/") &&
        typeof version === "string" &&
        version.trim().length > 0)
        .map(([name, version]) => [name, version.trim()]));
}
function injectedPackageVersions() {
    if (typeof __AGENT_NATIVE_PACKAGE_VERSIONS__ !== "undefined") {
        return readPackageVersions(__AGENT_NATIVE_PACKAGE_VERSIONS__);
    }
    return readPackageVersions(globalThis.__AGENT_NATIVE_PACKAGE_VERSIONS__);
}
export function getAgentNativePackageVersions() {
    return Object.entries(injectedPackageVersions())
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([name, version]) => ({ name, version }));
}
export function getAgentNativeDiagnostics() {
    return {
        buildId: clientBuildId() || "development",
        environment: injectedAgentNativeConfig().deployment?.environment ?? "unknown",
        packages: Object.fromEntries(getAgentNativePackageVersions().map(({ name, version }) => [
            name,
            version,
        ])),
    };
}
export function formatAgentNativeDiagnostics() {
    return JSON.stringify(getAgentNativeDiagnostics(), null, 2);
}
